// PATCH: hand-authored client-side PDF renderer wrapper for the SPA's bundled MN/jsPDF path.

// defaultPDFFooter mirrors the partitaiva24 SPA's footer text on every page —
// the same line you'd see clicking "Scarica PDF" in the web app.
const defaultPDFFooter = "Generato da PARTITA IVA 24 - www.partitaiva24.it"

func newInvoicesDownloadPdfCmd(flags *rootFlags) *cobra.Command {
	var outputPath string
	var launch bool
	var noFooter bool

	cmd := &cobra.Command{
		Use:   "download-pdf <id>",
		Short: "Render an invoice PDF using the Partitaiva24 web app renderer",
		Long: `Generate a PDF for the given invoice using partitaiva24's bundled jsPDF
renderer. The output matches the "Scarica PDF" button in the SPA.

Footer. By default the page footer carries the same line the web app uses:
"Generato da PARTITA IVA 24 - www.partitaiva24.it". Pass --no-footer to
suppress it (clean professional output, no watermark).`,
		Example: `  partitaiva24-pp-cli invoices download-pdf <id> -o invoice.pdf
  partitaiva24-pp-cli invoices download-pdf <id> -o invoice.pdf --no-footer
  partitaiva24-pp-cli invoices download-pdf <id> -o invoice.pdf --launch`,
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				return json.NewEncoder(cmd.OutOrStdout()).Encode(map[string]any{
					"action": "would-download",
					"path":   outputPath,
				})
			}
			if outputPath == "" {
				return usageErr(fmt.Errorf("--output is required"))
			}
			if err := checkPDFBundleFreshness(); err != nil {
				return err
			}
			nodePath, nodeVersion, err := findNode18()
			if err != nil {
				return err
			}
			_ = nodeVersion

			payload, err := loadPDFPayload(cmd, flags, args[0])
			if err != nil {
				return err
			}
			// Inject footer: default = SPA watermark, --no-footer = empty string.
			if noFooter {
				payload["footerText"] = ""
			} else {
				payload["footerText"] = defaultPDFFooter
			}
			pdfBytes, warnings, err := runPDFRenderer(nodePath, payload)
			if err != nil {
				if warnings != "" {
					return fmt.Errorf("%w\nrenderer diagnostics:\n%s", err, warnings)
				}
				return err
			}
			if len(pdfBytes) == 0 {
				return fmt.Errorf("renderer returned an empty PDF")
			}
			if err := os.MkdirAll(filepath.Dir(outputPath), 0o755); err != nil && filepath.Dir(outputPath) != "." {
				return err
			}
			if err := os.WriteFile(outputPath, pdfBytes, 0o644); err != nil {
				return err
			}
			if launch {
				if err := launchPath(outputPath); err != nil {
					return err
				}
			}
			if flags.asJSON {
				return json.NewEncoder(cmd.OutOrStdout()).Encode(map[string]any{
					"path":  outputPath,
					"bytes": len(pdfBytes),
				})
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Wrote %s (%d bytes)\n", outputPath, len(pdfBytes))
			return nil
		},
	}

	cmd.Flags().StringVarP(&outputPath, "output", "o", "", "PDF output path")
	cmd.Flags().BoolVar(&launch, "launch", false, "Open the PDF after writing it")
	cmd.Flags().BoolVar(&noFooter, "no-footer", false, "Suppress the partitaiva24 footer watermark")
	return cmd
}

func checkPDFBundleFreshness() error {
	generatedAt, err := time.Parse("2006-01-02", pdfgen.BundleGeneratedAt)
	if err != nil {
		return fmt.Errorf("invalid embedded PDF bundle timestamp %q: %w", pdfgen.BundleGeneratedAt, err)
	}
	if time.Since(generatedAt) > 30*24*time.Hour {
		return fmt.Errorf("embedded Partitaiva24 PDF bundle was generated on %s; run `make pdfgen` to refresh it", pdfgen.BundleGeneratedAt)
	}
	return nil
}

func findNode18() (string, string, error) {
	nodePath, err := exec.LookPath("node")
	if err != nil {
		return "", "", fmt.Errorf("node v18+ required (this CLI uses partitaiva24's bundled jsPDF renderer to produce the same PDF as the SPA's Scarica PDF button)")
	}
	out, err := exec.Command(nodePath, "--version").Output()
	if err != nil {
		return "", "", fmt.Errorf("checking node version: %w", err)
	}
	version := strings.TrimSpace(strings.TrimPrefix(string(out), "v"))
	majorText := strings.Split(version, ".")[0]
	major, err := strconv.Atoi(majorText)
	if err != nil || major < 18 {
		return "", "", fmt.Errorf("node v18+ required (this CLI uses partitaiva24's bundled jsPDF renderer to produce the same PDF as the SPA's Scarica PDF button); found v%s", version)
	}
	return nodePath, "v" + version, nil
}

func loadPDFPayload(cmd *cobra.Command, flags *rootFlags, invoiceID string) (map[string]any, error) {
	c, err := flags.newClient()
	if err != nil {
		return nil, err
	}

	invoicePath := replacePathParam("/user/invoices/{id}", "id", invoiceID)
	invoiceData, _, err := resolveRead(cmd.Context(), c, flags, "invoices", false, invoicePath, map[string]string{}, nil)
	if err != nil {
		return nil, classifyAPIError(err, flags)
	}
	var invoice any
	if err := json.Unmarshal(invoiceData, &invoice); err != nil {
		return nil, fmt.Errorf("decoding invoice response: %w", err)
	}

	user := map[string]any{}
	accountData, _, err := resolveRead(cmd.Context(), c, flags, "account", false, "/user/profile", map[string]string{}, nil)
	if err == nil {
		_ = json.Unmarshal(accountData, &user)
	}

	var invoiceSettings any = map[string]any{}
	if defaults, ok := user["invoice_defaults"]; ok && defaults != nil {
		invoiceSettings = defaults
	}

	return map[string]any{
		"invoice":         invoice,
		"invoiceSettings": invoiceSettings,
		"user":            user,
	}, nil
}

func runPDFRenderer(nodePath string, payload map[string]any) ([]byte, string, error) {
	tempDir, err := os.MkdirTemp("", "p24-pdfgen-*")
	if err != nil {
		return nil, "", err
	}
	defer os.RemoveAll(tempDir)

	assetsDir := filepath.Join(tempDir, "assets")
	if err := os.MkdirAll(assetsDir, 0o755); err != nil {
		return nil, "", err
	}
	if err := os.WriteFile(filepath.Join(tempDir, "render-pdf.js"), pdfgen.RenderPDFScript, 0o644); err != nil {
		return nil, "", err
	}
	if err := os.WriteFile(filepath.Join(assetsDir, "bundle.patched.js"), pdfgen.RenderPDFBundle, 0o644); err != nil {
		return nil, "", err
	}

	stdin, err := json.Marshal(payload)
	if err != nil {
		return nil, "", err
	}
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	renderCmd := exec.Command(nodePath, filepath.Join(tempDir, "render-pdf.js"))
	renderCmd.Dir = tempDir
	renderCmd.Stdin = bytes.NewReader(stdin)
	renderCmd.Stdout = &stdout
	renderCmd.Stderr = &stderr
	renderCmd.Env = append(os.Environ(), "NODE_PATH="+pdfgenNodeModulesPath())

	if err := renderCmd.Run(); err != nil {
		return nil, stderr.String(), fmt.Errorf("rendering PDF with Partitaiva24 bundled renderer: %w", err)
	}
	return stdout.Bytes(), stderr.String(), nil
}

func pdfgenNodeModulesPath() string {
	if override := os.Getenv("P24_PDFGEN_NODE_PATH"); override != "" {
		return override
	}
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return ""
	}
	return filepath.Clean(filepath.Join(filepath.Dir(file), "..", "pdfgen", "node_modules"))
}

func launchPath(path string) error {
	switch runtime.GOOS {
	case "darwin":
		return exec.Command("open", path).Start()
	case "linux":
		return exec.Command("xdg-open", path).Start()
	default:
		return fmt.Errorf("--launch is not supported on %s", runtime.GOOS)
	}
}
